# Expressive Functional Pipelines in GDScript 2.0:
static func playable_cards_in_hand(hand: Array[CardData], top: CardData) -> Array[CardData]:
    return hand.filter(func(c: CardData) -> bool:
        return RuleValidator.is_single_card_playable(c, top, GameState.penalty_stack, GameState.declared_suit)
    )

static func total_hand_points(hand: Array[CardData]) -> int:
    return hand.reduce(func(acc: int, c: CardData) -> int:
        return acc + TournamentRules.card_points(c), 0
    )

static func holds_penalty_blocker(hand: Array[CardData]) -> bool:
    return hand.any(func(c: CardData) -> bool: return c.rank == CardTypes.Ranks.ACE)

# Self-Validating Property Setter with Signal Emission:
signal health_changed(current: int, maximum: int)
signal defeated()

@export var max_hp: int = 100
var hp: int = 100:
    set(value):
        var next_hp: int = clampi(value, 0, max_hp)
        if next_hp == hp:
            return
        hp = next_hp
        health_changed.emit(hp, max_hp)
        if hp == 0:
            defeated.emit()

