# Choreographing Animated Card Dealing & Modal Input with await:
func deal_opening_hands_animated(cards_each: int = 4) -> void:
    play_button.disabled = true
    for _round in range(cards_each):
        for seat in range(4):
            GameState.draw_cards(seat, 1)
            await get_tree().create_timer(0.08).timeout
    play_button.disabled = false

func prompt_human_for_suit() -> int:
    declare_suit_dialog.show()
    # Pauses this function until suit_declared(suit) emits, then returns suit!
    var chosen_suit: int = await declare_suit_dialog.suit_declared
    return chosen_suit

