# Strategy Pattern: Pluggable AI Personality Resources
class_name AIStrategy
extends Resource

@export var personality_name: String = "Balanced"
@export var ace_conservation_bias: int = 35
@export var penalty_aggression_bonus: int = 20

func evaluate_move(cards: Array[CardData], active_penalty: int, hand_size: int) -> int:
    var score: int = 0
    for c in cards:
        score += TournamentRules.card_points(c)
        if c.is_penalty():
            score += penalty_aggression_bonus
        if c.rank == CardTypes.Ranks.ACE and active_penalty == 0 and hand_size > 2:
            score -= ace_conservation_bias
    return score

# Object Pool Helper for Zero-Allocation UI & Projectile Reuse:
class_name NodePool
extends RefCounted

var _scene: PackedScene
var _inactive: Array[Node] = []

func _init(template_scene: PackedScene, prewarm_count: int = 8) -> void:
    _scene = template_scene
    for _i in range(prewarm_count):
        _inactive.append(_scene.instantiate())

func acquire(parent: Node) -> Node:
    var instance: Node = _inactive.pop_back() if not _inactive.is_empty() else _scene.instantiate()
    if instance.get_parent() != parent:
        parent.add_child(instance)
    if instance is CanvasItem:
        instance.visible = true
    return instance

func release(instance: Node) -> void:
    if instance is CanvasItem:
        instance.visible = false
    _inactive.push_back(instance)

